/**
 * @summary Extract allowed values from an uploaded document with Gemini
 */
export const extractGeminiDocumentBodyContentBase64Min = 4;
export const extractGeminiDocumentBodyContentBase64Max = 11184812;

export const extractGeminiDocumentBodyMimeTypeMax = 255;

export const extractGeminiDocumentBodyMimeTypeRegExp = new RegExp(
  "^[A-Za-z0-9][A-Za-z0-9!#$&^_.+-]*/[A-Za-z0-9][A-Za-z0-9!#$&^_.+-]*$",
);
export const extractGeminiDocumentBodyStepsItemMax = 2000;

export const extractGeminiDocumentBodyStepsMax = 20;

export const extractGeminiDocumentBodyDestinationMax = 2000;

export const extractGeminiDocumentBodyAllowedFieldsItemMax = 200;

export const extractGeminiDocumentBodyAllowedFieldsMax = 100;

export const extractGeminiDocumentBodyProfileIdMax = 200;

export const extractGeminiDocumentBodyProfileVersionMultipleOf = 1;

export const extractGeminiDocumentBodyDocumentTypeMax = 200;

export const extractGeminiDocumentBodyExamplesMax = 4000;

export const ExtractGeminiDocumentBody = zod.object({
  contentBase64: zod
    .string()
    .min(extractGeminiDocumentBodyContentBase64Min)
    .max(extractGeminiDocumentBodyContentBase64Max),
  mimeType: zod
    .string()
    .min(1)
    .max(extractGeminiDocumentBodyMimeTypeMax)
    .regex(extractGeminiDocumentBodyMimeTypeRegExp),
  steps: zod
    .array(zod.string().min(1).max(extractGeminiDocumentBodyStepsItemMax))
    .min(1)
    .max(extractGeminiDocumentBodyStepsMax),
  destination: zod.string().max(extractGeminiDocumentBodyDestinationMax),
  allowedFields: zod
    .array(
      zod.string().min(1).max(extractGeminiDocumentBodyAllowedFieldsItemMax),
    )
    .max(extractGeminiDocumentBodyAllowedFieldsMax),
  profileId: zod.string().max(extractGeminiDocumentBodyProfileIdMax).optional(),
  profileVersion: zod
    .number()
    .min(1)
    .multipleOf(extractGeminiDocumentBodyProfileVersionMultipleOf)
    .optional(),
  documentType: zod
    .string()
    .max(extractGeminiDocumentBodyDocumentTypeMax)
    .optional(),
  examples: zod.string().max(extractGeminiDocumentBodyExamplesMax).optional(),
});

export const ExtractGeminiDocumentResponse = zod.object({
  text: zod.string(),
  source: zod.string(),
  values: zod.record(zod.string(), zod.string()),
});

